    "alert_id": "EX4_001",
    "title": "Carbamazepine contraindicated with DTG",
    "message": "Guidelines list carbamazepine as a contraindication for DTG, and state it decreases DTG levels by 30–70%. The patient started carbamazepine 2 weeks ago while on DTG. Viral load rose from <50 to 1,240 copies/mL despite reported good adherence, consistent with subtherapeutic DTG levels. Guidelines recommend using valproic acid instead. The clinician's plan to reduce carbamazepine dose does not address the interaction.",
    "issue_type": "drug_interaction",
    "severity": "critical",
    "recommended_action": "Discontinue carbamazepine and use valproic acid for seizure management as per guidelines. Repeat viral load after switching.",
    "citations": [
      {"page_number": 10, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p10_c1"},
      {"page_number": 49, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p49_c1"}
    ]
  },
  {
    "alert_id": "EX4_002",
    "title": "Carbamazepine toxicity with hyponatremia",
    "message": "Patient has carbamazepine level 14 mcg/mL (therapeutic 4–12), hyponatremia (Na 128 mmol/L), nystagmus, ataxia, and tremor. Carbamazepine is a known cause of SIADH and hyponatremia. Valproate may also contribute to hyponatremia. The clinician plans dose reduction and repeat level, which is appropriate. Sodium should be monitored closely and corrected as needed.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Reduce carbamazepine dose as planned, repeat level and sodium. Consider switching to valproic acid monotherapy to eliminate the DTG interaction.",
    "citations": []
  },
  {
    "alert_id": "EX4_003",
    "title": "Detectable viral load needs adherence review",
    "message": "Guidelines state a repeat viral load >1000 copies/mL suggests treatment failure, requiring HIV drug resistance testing and switch after ruling out adherence issues. This patient's VL of 1,240 copies/mL exceeds that threshold. The likely cause is the carbamazepine–DTG interaction reducing DTG levels, but the clinician's plan does not address the VL or outline next steps for resistance testing or regimen review.",
    "issue_type": "plan_add",
    "severity": "high",
    "recommended_action": "Address the carbamazepine–DTG interaction first. Repeat viral load after correction; if still >1000, proceed to HIV drug resistance testing.",
    "citations": [
      {"page_number": 50, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p50_c2"}
    ]
  },
  {
    "alert_id": "EX4_004",
    "title": "Elevated ALT with hepatotoxic drugs",
    "message": "ALT is 68 U/L. Both carbamazepine and valproate can cause hepatotoxicity; TDF has also been associated with liver enzyme derangement. Guidelines recommend LFTs and RFTs when TDF-related toxicity is suspected. The combination of two hepatotoxic anticonvulsants plus TDF compounds risk. Non-drug causes should also be considered. The clinician's plan does not include ALT follow-up.",
    "issue_type": "toxicity",
    "severity": "moderate",
    "recommended_action": "Repeat ALT after carbamazepine dose adjustment. If persistently elevated, evaluate for drug-induced liver injury and consider regimen review.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"}
    ]
  }
]

plan_text:
{
  "art_regimen_decision": {
    "decision": "Continue",
    "reason": "Current TDF/3TC/DTG regimen is not implicated in the patient's toxicity symptoms, which are attributed to carbamazepine; ALT and creatinine are not markedly abnormal."
  },
  "problems": [
    {
      "problem": "Carbamazepine toxicity (ataxia, nystagmus, tremor, level 14)",
      "action": "Reduce carbamazepine dose as planned and repeat carbamazepine level to confirm reduction into therapeutic range.",
      "reason": "Patient has classic carbamazepine toxicity signs (horizontal nystagmus, wide-based gait, fine tremor) with a supra-therapeutic level of 14, and the clinician's plan to reduce dose and repeat the level is appropriate.",
      "clinician_plan_for_this_problem": {
        "decision": "Agree",
        "explanation": "The clinician correctly identified carbamazepine toxicity and planned dose reduction with repeat level monitoring."
      }
    },
    {
      "problem": "Detectable viral load (1,240 copies/mL) after prior suppression",
      "action": "Conduct enhanced adherence counseling and repeat viral load in 3 months; investigate potential drug-drug interaction between carbamazepine and DTG.",
      "reason": "Patient was suppressed (<50 copies/mL) in September 2025 but now has low-level viremia at 1,240 copies/mL with good reported adherence, and carbamazepine is a known CYP3A4 inducer that may reduce DTG concentrations.",
      "clinician_plan_for_this_problem": {
        "decision": "Gap",
        "explanation": "The clinician noted the detectable viral load and was unsure of the cause but did not investigate the potential carbamazepine-DTG interaction or plan enhanced adherence counseling."
      }
    },
    {
      "problem": "Potential DTG-carbamazepine drug interaction reducing ART efficacy",
      "action": "Consult pharmacist or neurologist about alternative antiepileptic compatible with DTG, or consider switching antiepileptic to one without CYP induction effects.",
      "reason": "Carbamazepine is a potent enzyme inducer that can lower DTG plasma levels, potentially contributing to the new detectable viral load despite good adherence.",
      "clinician_plan_for_this_problem": {
        "decision": "Not Addressed",
        "explanation": "The clinician's plan does not mention or investigate the potential interaction between carbamazepine and DTG as a cause of the detectable viral load."
      }
    },
    {
      "problem": "Mildly elevated ALT (68 U/L)",
      "action": "Monitor liver function tests; trend ALT with repeat test in 2-4 weeks; evaluate if carbamazepine dose reduction leads to ALT improvement.",
      "reason": "ALT is mildly elevated and both carbamazepine and antiretrovirals can cause hepatotoxicity, so monitoring is warranted to ensure it does not progress.",
      "clinician_plan_for_this_problem": {
        "decision": "Not Addressed",
        "explanation": "The clinician's plan does not mention follow-up of the mildly elevated ALT despite the patient being on multiple hepatotoxic agents."
      }
    }
  ],
  "monitoring_plan": [
    "Repeat carbamazepine level after dose reduction to confirm therapeutic range",
    "Repeat viral load in 3 months after addressing adherence and potential drug-drug interaction",
    "Repeat ALT in 2-4 weeks to monitor trend",
    "Monitor renal function (creatinine) at next routine visit given TDF use"
  ],
  "patient_counselling": [
    "Explain that carbamazepine toxicity is causing the neurological symptoms and the dose will be reduced.",
    "Counsel on the importance of adherence to ART and the potential interaction between carbamazepine and DTG.",
    "Advise to report any worsening neurological symptoms, rash, or jaundice promptly.",
    "Educate that the detectable viral load needs investigation and repeat testing in 3 months."
  ]
}
